SELECT

FROM builtin_skills
WHERE deleted_at IS NULL
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT

FROM builtin_skill_versions
WHERE skill_id = #{skillID}
AND deleted_at IS NULL
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT

FROM builtin_skill_versions
WHERE skill_external_id = #{skillExternalID}
AND version = #{version}
AND deleted_at IS NULL
